class UserRepository:
    """
    간단한 인메모리 사용자 저장소.
    각 인스턴스는 독립적인 저장소를 가진다.
    """

    def __init__(self):
        self._users = {}  # 인스턴스 변수 (올바름)

    def add_user(self, user_id: str, name: str, email: str) -> dict:
        """
        새 사용자를 추가한다.
        이미 존재하는 user_id면 ValueError 발생.
        """
        if user_id in self._users:
            raise ValueError(f"User {user_id} already exists")
        self._users[user_id] = {
            "id": user_id,
            "name": name,
            "email": email
        }
        return self._users[user_id].copy()

    def get_user(self, user_id: str) -> dict | None:
        """
        user_id로 사용자를 조회한다.
        없으면 None 반환.
        """
        user = self._users.get(user_id)
        if user is None:
            return None
        return user.copy()

    def update_user(self, user_id: str, **kwargs) -> dict:
        """
        사용자 정보를 부분 업데이트한다.
        없는 user_id면 ValueError 발생.
        기존 필드는 유지되고 전달된 필드만 변경된다.
        """
        if user_id not in self._users:
            raise ValueError(f"User {user_id} not found")
        self._users[user_id].update(kwargs)
        return self._users[user_id].copy()

    def delete_user(self, user_id: str) -> bool:
        """
        사용자를 삭제한다.
        삭제 성공하면 True, 없으면 False 반환.
        """
        if user_id in self._users:
            del self._users[user_id]
            return True
        return False

    def count_users(self) -> int:
        """
        현재 저장된 사용자 수를 반환한다.
        """
        return len(self._users)

