            # BUG: 실제로 삭제하지 않고 플래그만 설정
            self._users[user_id]["_deleted"] = True
            return True
        return False

    def count_users(self) -> int:
        # BUG: 삭제된 사용자도 카운트됨
        return len(self._users)
